import json,subprocess,hashlib,datetime
from pathlib import Path
source='''package TriggerArgumentProbe {
  action def Test {
    action wrongAfter accept after true;
    action wrongAt accept at false;
    action wrongWhen accept when 1;
  }
}
'''
request={'revision':1,'documents':[{'id':'trigger-argument-probe','name':'trigger-argument-probe.sysml','text':source}]}
payload=json.dumps(request).encode();binary=Path('target/release/sysml-inspect');sha=lambda b:hashlib.sha256(b).hexdigest();before=sha(binary.read_bytes())
run=subprocess.run([str(binary),'--request-json'],input=payload,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=30)
assert run.returncode==0,run.stderr.decode()
snapshot=json.loads(run.stdout);assert snapshot['engineVersion'].endswith('.24')
assert all(d['stage']=='semantic' for d in snapshot['diagnostics']), snapshot['diagnostics']
assert len(snapshot['diagnostics'])==3
assert before==sha(binary.read_bytes())
expected=['validateTriggerInvocationExpressionAfterArgument','validateTriggerInvocationExpressionAtArgument','validateTriggerInvocationExpressionWhenArgument']
print(json.dumps(snapshot['diagnostics'],indent=2))
record={
 'generatedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),
 'scope':'Full-library public analysis of three invalid trigger arguments. This probes emitted diagnostic identifiers and positive rejection only; it does not establish complete validation or measure all missing conditions.',
 'request':request,'requestSha256':sha(payload),'responseSha256':sha(run.stdout),
 'engineVersion':snapshot['engineVersion'],'binarySha256':before,
 'kernelInputSha256':subprocess.check_output(['node','--input-type=module','-e',"import {kernelInputHash} from './tools/lib/kernel-inputs.mjs'; process.stdout.write(kernelInputHash(process.cwd()));"],text=True),
 'command':[str(binary),'--request-json'],'exitCode':run.returncode,
 'expectedCanonicalRules':expected,'diagnostics':snapshot['diagnostics'],
 'canonicalRulesObserved':[name for name in expected if any(d['code']==name for d in snapshot['diagnostics'])],
 'sourceAnchors':['SYSML-XMI-Systems-Actions-TriggerInvocationExpression-'+name for name in expected],
 'reproductionScript':Path(__file__).read_text(),
}
Path('docs/evidence/trigger-argument-validation-before-macos-arm64.json').write_text(json.dumps(record,indent=2)+'\n')
